mapper.update:
UPDATE prd_document SET current_version_id = NULL, current_score = NULL,
    status = CASE WHEN status = 'ARCHIVED' THEN status ELSE 'DRAFT' END, updated_at = now()
WHERE id = #{prdId}

mapper.delete:
DELETE FROM prd_patch p WHERE p.status != 'APPLIED' AND (
    p.source_version_id = #{versionId} OR p.source_finding_id IN (
        SELECT f.id FROM review_finding f JOIN review_report r ON r.id = f.report_id
        JOIN review_job j ON j.id = r.review_job_id WHERE j.prd_version_id = #{versionId}
    )
)
